const rows = items.map(i => i.json);

// „Deja trimis" are DOUA forme in Sheet, pentru ca doua sisteme scriu col R:
//   - Sistemul A (Apps Script -> FastAPI) scrie 'sent'
//   - Sistemul B (--step poll)          scrie 'GESENDET'
// Daca recunoastem doar una, un rand deja aplicat e retrimis de celalalt sistem.
const SENT = ['GESENDET', 'SENT', 'DRY_RUN'];
const isSent = r => SENT.includes(String(r['Email Status'] || '').trim().toUpperCase());

const pending = rows.filter(r =>
  String(r['Sende Befehl'] || '').trim().toUpperCase() === 'SENDEN' && !isSent(r)
);

// Proiectie explicita — agentii din pipeline au nevoie si de Standort/Kontakt
// Person/Datum gefunden, altfel Anschreiben-ul se genereaza fara ele.
const commands = pending.map(r => ({
  action: 'send',
  'Apply URL': r['Apply URL'],
  Firma: r['Firma'],
  Position: r['Position'],
  Standort: r['Standort'],
  'Kontakt Email': r['Kontakt Email'],
  'Kontakt Person': r['Kontakt Person'],
  Sprache: r['Sprache'],
  Quelle: r['Quelle'],
  'Datum gefunden': r['Datum gefunden'],
  'Anschreiben PDF': r['Anschreiben PDF'],
  'Email Status': r['Email Status'],
}));

return [{ json: { ok: true, commands } }];
